from fractions import Fraction
import re

def fraction_expr(s: str) -> str:
    # Tokenize input string
    # Tokens can be:
    # - Fraction literals (e.g. 3/4)
    # - Integer literals (e.g. 3)
    # - Operators: +, -, *
    # - Parentheses: (, )
    token_spec = [
        ('FRAC', r'\d+/\d+'),
        ('INT', r'\d+'),
        ('OP', r'[+*\-]'),
        ('LPAREN', r'\('),
        ('RPAREN', r'\)'),
        ('WS', r'\s+'),
        ('MISMATCH', r'.'),
    ]
    tok_regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in token_spec)

    raw_tokens = []
    for mo in re.finditer(tok_regex, s):
        kind = mo.lastgroup
        val = mo.group()
        if kind == 'WS':
            continue
        elif kind == 'MISMATCH':
            raise ValueError(f"Invalid character: {val}")
        elif kind == 'FRAC':
            num, den = val.split('/')
            if int(den) == 0:
                raise ValueError("Zero denominator")
            raw_tokens.append(('VAL', Fraction(int(num), int(den))))
        elif kind == 'INT':
            raw_tokens.append(('VAL', Fraction(int(val), 1)))
        elif kind == 'OP':
            raw_tokens.append(('OP', val))
        elif kind == 'LPAREN':
            raw_tokens.append(('LPAREN', val))
        elif kind == 'RPAREN':
            raw_tokens.append(('RPAREN', val))

    if not raw_tokens:
        raise ValueError("Empty expression")

    # Handle unary minus by converting unary '-' into (0 - term) or a special UNARY_MINUS operator
    # Unary '-' occurs at the start of expression or after another OP or after LPAREN.
    processed_tokens = []
    for i, token in enumerate(raw_tokens):
        kind, val = token
        if kind == 'OP' and val == '-':
            prev = processed_tokens[-1] if processed_tokens else None
            if prev is None or prev[0] in ('OP', 'LPAREN', 'UNARY_MINUS'):
                processed_tokens.append(('UNARY_MINUS', '~'))
                continue
        elif kind == 'OP' and val == '+':
            # Leading or redundant unary '+' can be ignored if right after OP/LPAREN
            prev = processed_tokens[-1] if processed_tokens else None
            if prev is None or prev[0] in ('OP', 'LPAREN', 'UNARY_MINUS'):
                continue
        processed_tokens.append(token)

    # Shunting-yard algorithm to convert to RPN
    precedence = {'+': 1, '-': 1, '*': 2, '~': 3}
    output = []
    op_stack = []

    for token in processed_tokens:
        kind, val = token
        if kind == 'VAL':
            output.append(token)
        elif kind == 'UNARY_MINUS':
            op_stack.append(token)
        elif kind == 'OP':
            while (op_stack and op_stack[-1][0] in ('OP', 'UNARY_MINUS') and
                   precedence[op_stack[-1][1]] >= precedence[val]):
                output.append(op_stack.pop())
            op_stack.append(token)
        elif kind == 'LPAREN':
            op_stack.append(token)
        elif kind == 'RPAREN':
            while op_stack and op_stack[-1][0] != 'LPAREN':
                output.append(op_stack.pop())
            if not op_stack or op_stack[-1][0] != 'LPAREN':
                raise ValueError("Mismatched parentheses")
            op_stack.pop()

    while op_stack:
        top = op_stack.pop()
        if top[0] in ('LPAREN', 'RPAREN'):
            raise ValueError("Mismatched parentheses")
        output.append(top)

    # Evaluate RPN
    eval_stack = []
    for token in output:
        kind, val = token
        if kind == 'VAL':
            eval_stack.append(val)
        elif kind == 'UNARY_MINUS':
            if not eval_stack:
                raise ValueError("Malformed expression")
            a = eval_stack.pop()
            eval_stack.append(-a)
        elif kind == 'OP':
            if len(eval_stack) < 2:
                raise ValueError("Malformed expression")
            b = eval_stack.pop()
            a = eval_stack.pop()
            if val == '+':
                eval_stack.append(a + b)
            elif val == '-':
                eval_stack.append(a - b)
            elif val == '*':
                eval_stack.append(a * b)
            else:
                raise ValueError(f"Unknown operator {val}")

    if len(eval_stack) != 1:
        raise ValueError("Malformed expression")

    res = eval_stack[0]
    if res.denominator == 1:
        return str(res.numerator)
    return f"{res.numerator}/{res.denominator}"
